#!/usr/bin/env python3
"""W_3(p,q) minimal model: python run_w3.py p q Dmax [prime].  Ideal generated by singular vectors at weight (p-2)(q-2);
dims cross-checked against max_submodule; reports non-arc (positive Li) minimal generators."""
import sys
from fractions import Fraction
from w3 import W3
from lie_voa_ss import SingularSupport, find_singular
from max_submodule import simple_quotient_dims, per_weight
p_, q_, Dmax = map(int, sys.argv[1:4]); P = int(sys.argv[4]) if len(sys.argv) > 4 else 2147483647
c = 2 * (1 - Fraction(12 * (p_ - q_) ** 2, p_ * q_))
alg = W3(c, P)
D0 = (p_ - 2) * (q_ - 2)
sv = find_singular(alg, D0, ())
print(f"W3({p_},{q_}) c={c}: singular vectors at weight {D0}: {len(sv)}", flush=True)
ss = SingularSupport(alg, Dmax, sv)
ss.run(gen_modes=[(1, 0), (2, 0), (1, 1), (2, 1), (3, 1)])
eng = {D: dV - dI for (D, dV, dI, ng) in ss.table}
ref = per_weight(simple_quotient_dims(alg, Dmax, [(-1, 0), (-2, 0), (-1, 1), (-2, 1)]))
mism = [(D, eng.get(D), ref.get(D)) for D in ref if eng.get(D) != ref.get(D)]
print("dims vs max-submodule:", "MATCH" if not mism else f"MISMATCH {mism[:6]}")
print("Li-0 generators (D,#):", [(g[0], g[3]) for g in ss.gens_found if g[1] == 0])
print("NON-ARC generators (D, Li, #):", [(g[0], g[1], g[3]) for g in ss.gens_found if g[1] > 0] or "none")
